<script nonce="{{ Vite::cspNonce() }}">(()=>{const sidebar=document.getElementById('adminSidebar'),overlay=document.getElementById('adminOverlay'),openButton=document.getElementById('openSidebar');const open=()=>{sidebar?.classList.remove('-translate-x-full');overlay?.classList.remove('hidden');document.body.classList.add('overflow-hidden');openButton?.setAttribute('aria-expanded','true')};const close=()=>{sidebar?.classList.add('-translate-x-full');overlay?.classList.add('hidden');document.body.classList.remove('overflow-hidden');openButton?.setAttribute('aria-expanded','false')};openButton?.addEventListener('click',open);document.getElementById('closeSidebar')?.addEventListener('click',close);overlay?.addEventListener('click',close);document.addEventListener('keydown',event=>{if(event.key==='Escape')close()})})();</script>@stack('scripts')</body></html>
